class Solution {
public:
    int longestPath(vector<int>& parent, string s) {
        int n = parent.size();
        vector<vector<int>> children(n);
        for (int i = 1; i < n; i++) {
            children[parent[i]].push_back(i);
        }

        vector<int> order;
        order.reserve(n);
        vector<int> stk;
        stk.reserve(n);
        stk.push_back(0);
        while (!stk.empty()) {
            int u = stk.back();
            stk.pop_back();
            order.push_back(u);
            for (int v : children[u]) {
                stk.push_back(v);
            }
        }

        vector<int> down(n, 1);
        int ans = 1;
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            int first = 0, second = 0;
            for (int v : children[u]) {
                if (s[v] != s[u]) {
                    int len = down[v];
                    if (len > first) {
                        second = first;
                        first = len;
                    } else if (len > second) {
                        second = len;
                    }
                }
            }
            down[u] = 1 + first;
            int through = 1 + first + second;
            if (through > ans) ans = through;
        }
        return ans;
    }
};
